mapper.select:
select * from public.vault_item
where vault_id = #{vaultId} and generation = #{generation} and item_id = #{itemId}
for update

select * from public.vault_item
where vault_id = #{vaultId} and generation = #{generation} and is_deleted = true
and gmt_deleted > #{before} and gmt_deleted <= #{firstTime}

    and (gmt_deleted < #{lastDeleted} or (gmt_deleted = #{lastDeleted} and item_id > #{lastId}))

order by gmt_deleted desc, item_id asc
limit #{limit}

select min(gmt_deleted) from public.vault_item
where vault_id = #{vaultId} and generation = #{generation} and is_deleted = true
and gmt_deleted > #{before}

select count(*) from public.vault_item
where vault_id = #{vaultId} and generation = #{generation}
and (is_deleted = false or gmt_deleted > #{before})

mapper.insert:
insert into public.vault_rotation_expected_item (
    rotation_id, item_id, source_content_version, source_row_version, target_content_version,
    gmt_create, gmt_modified, create_user, update_user
)
select #{rotationId}, item_id, content_version, row_version, content_version, #{now}, #{now}, #{actor}, #{actor}
from public.vault_item
where vault_id = #{vaultId} and generation = #{generation}
and (is_deleted = false or gmt_deleted > #{before})

mapper.select:
select


        i.item_id, i.content_version, i.row_version, i.key_epoch, i.is_deleted, i.gmt_deleted, i.delete_user

    i.*

from public.vault_item i
join public.vault_rotation_expected_item e on e.item_id = i.item_id and e.rotation_id = #{rotationId}
where i.vault_id = #{vaultId} and i.generation = #{generation} and e.is_deleted = false

    and i.item_id > #{lastId}

order by i.item_id

    limit #{limit}

select item_id, content_version, row_version, key_epoch, is_deleted, gmt_deleted, delete_user from public.vault_item
where vault_id = #{vaultId} and generation = #{generation}
order by item_id

select * from public.vault_item
where vault_id = #{vaultId} and generation = #{generation}
order by item_id

mapper.update:
update public.vault_item
set is_deleted = false, delete_user = null, gmt_deleted = null,
    update_user = #{actor}, gmt_modified = #{now}, row_version = row_version + 1
where vault_id = #{item.vaultId} and generation = #{item.generation} and item_id = #{item.itemId}
and row_version = #{item.rowVersion} and is_deleted = true and gmt_deleted > #{before}

mapper.delete:
delete from public.vault_item
where vault_id = #{item.vaultId} and generation = #{item.generation} and item_id = #{item.itemId}
and row_version = #{item.rowVersion} and is_deleted = true

delete from public.vault_item
where vault_id = #{item.vaultId} and generation = #{item.generation} and item_id = #{item.itemId}
and row_version = #{item.rowVersion} and is_deleted = false

delete from public.vault_item where id in (
    select i.id from public.vault_item i
    where i.vault_id = #{vaultId} and i.is_deleted = true and i.gmt_deleted <= #{before}
    and not exists (
        select 1 from public.vault_rotation r
        where r.vault_id = i.vault_id and r.status = 'UPLOADING' and r.is_deleted = false
    )
    order by i.gmt_deleted, i.id

        limit #{limit}

    for update skip locked
)
